package fr.cercle.decoupe;
import java.util.*;
public class Engine{
 public final int mode;public Random rng;public int score,round,hp,maxHp,enemy,enemyMax,intent,power,armor,energy,poison,leech,counter,turn,cuts,target,stage,bumps;public boolean over,won,upgrade;public int[] offers=new int[3];public String message="";public ArrayList<float[]> polygon=new ArrayList<>(),partA=new ArrayList<>(),partB=new ArrayList<>();public float x,y,time,tx,ty;public boolean moving;public boolean[] gems=new boolean[3];public int[] gaps=new int[3];
 public Engine(int m,long seed){mode=m;rng=new Random(seed);reset();}public void reset(){score=round=turn=cuts=stage=bumps=0;hp=maxHp=42;power=8;armor=poison=leech=counter=0;energy=3;over=won=upgrade=false;message="";if(mode==0)room();if(mode==1)plate();if(mode==2)course();}
 public void room(){enemyMax=round==5?42:14+round*3;enemy=enemyMax;intent=rng.nextInt(2);upgrade=false;message="Lis l’intention, puis choisis ton geste.";}
 public String intentName(){return new String[]{"FRAPPE : "+Math.max(1,7+round-armor)+" dégâts","PRÉPARE un coup puissant","COUP PUISSANT : "+Math.max(1,13+round-armor)+" dégâts","SE PROTÈGE : dégâts reçus divisés par 2"}[intent];}
 public boolean act(int a){if(over||upgrade||a<0||a>2||a==2&&energy==0)return false;int damage=0;if(a==0){damage=power;energy=Math.min(3,energy+1);}if(a==1){energy=Math.min(3,energy+1);if(intent==0||intent==2)damage=2+counter;}if(a==2){energy--;damage=counter;}if(intent==3)damage=(damage+1)/2;enemy-=damage+poison;if(a==0&&damage>0)hp=Math.min(maxHp,hp+leech);turn++;
 if(enemy<=0){score+=100+hp;round++;if(round==6){won=over=true;message="Les six portes sont franchies.";}else{upgrade=true;ArrayList<Integer> ids=new ArrayList<>();for(int i=0;i<6;i++)ids.add(i);Collections.shuffle(ids,rng);for(int i=0;i<3;i++)offers[i]=ids.get(i);}return true;}
 int hit=intent==0?7+round:intent==2?13+round:0;if(a==2)hit=0;else if(a==1)hit=Math.max(0,hit-9);hp-=Math.max(0,hit-armor);message=hit==0?"Aucun dégât reçu.":"L’ennemi riposte : "+Math.max(0,hit-armor)+" PV.";intent=(intent+1)%4;if(hp<=0){hp=0;over=true;message="La prochaine tentative sera différente.";}return true;}
 public String offerName(int id){return new String[]{"LAME +2","ARMURE +1","SOUFFLE +14 PV","POISON +2 / tour","VOL DE VIE +2","RIPOSTE +3"}[id];}
 public void choose(int n){if(!upgrade||n<0||n>2)return;switch(offers[n]){case 0:power+=2;break;case 1:armor++;break;case 2:maxHp+=4;hp=Math.min(maxHp,hp+14);break;case 3:poison+=2;break;case 4:leech+=2;break;case 5:counter+=3;break;}room();}
 public void plate(){polygon.clear();polygon.add(new float[]{100,390});polygon.add(new float[]{620,390});polygon.add(new float[]{620,930});polygon.add(new float[]{100,930});cuts=stage=0;target=new int[]{50,35,65}[round];partA.clear();partB.clear();message="Trace un trait, puis touche le fragment à garder.";}
 public static float area(List<float[]> p){float a=0;for(int i=0;i<p.size();i++){float[] u=p.get(i),v=p.get((i+1)%p.size());a+=u[0]*v[1]-v[0]*u[1];}return Math.abs(a)/2;}
 public static float side(float[] p,float ax,float ay,float bx,float by){return (bx-ax)*(p[1]-ay)-(by-ay)*(p[0]-ax);}
 public static ArrayList<float[]> clip(List<float[]> p,float ax,float ay,float bx,float by,boolean positive){ArrayList<float[]> out=new ArrayList<>();for(int i=0;i<p.size();i++){float[] a=p.get(i),b=p.get((i+1)%p.size());float da=side(a,ax,ay,bx,by)*(positive?1:-1),db=side(b,ax,ay,bx,by)*(positive?1:-1);if(da>=0)out.add(a.clone());if((da>0&&db<0)||(da<0&&db>0)){float t=da/(da-db);out.add(new float[]{a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])});}}return out;}
 public static boolean inside(List<float[]> p,float x,float y){boolean in=false;for(int i=0,j=p.size()-1;i<p.size();j=i++){float[] a=p.get(i),b=p.get(j);if((a[1]>y)!=(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])in=!in;}return in;}
 public void cut(float ax,float ay,float bx,float by){if(over||stage!=0||cuts>=2||Math.hypot(bx-ax,by-ay)<25)return;partA=clip(polygon,ax,ay,bx,by,true);partB=clip(polygon,ax,ay,bx,by,false);if(area(partA)<100||area(partB)<100){message="Le trait doit traverser la plaque.";return;}stage=1;message="Touche la partie que tu veux garder.";}
 public void keep(float px,float py){if(stage!=1)return;if(inside(partA,px,py))polygon=partA;else if(inside(partB,px,py))polygon=partB;else return;partA=new ArrayList<>();partB=new ArrayList<>();stage=0;cuts++;message="Conservé : "+Math.round(percent())+" %. Tu peux valider.";}
 public float percent(){return area(polygon)/(520*540)*100;}
 public void validate(){if(over||stage!=0)return;if(cuts==0){message="Trace d’abord un trait et choisis une partie.";return;}score+=Math.max(0,Math.round(100-Math.abs(percent()-target)*4));round++;if(round==3){won=over=true;}else plate();}
 public void course(){x=360;y=970;tx=x;ty=y;moving=false;time=0;gems=new boolean[3];for(int i=0;i<3;i++)gaps[i]=(i+round)%2==0?200:520;message="Passe par les portes claires. Attends si elles ferment.";}
 public boolean open(int i){return (time+i*.7f)%3.6f<2.35f;}
 public void tick(float dt){if(mode!=2||over)return;dt=Math.min(.04f,Math.max(0,dt));time+=dt;if(!moving)return;float dx=tx-x,dy=ty-y,d=(float)Math.hypot(dx,dy),step=Math.min(d,260*dt);if(d<1)return;float nx=Math.max(78,Math.min(642,x+dx/d*step)),ny=Math.max(365,Math.min(985,y+dy/d*step));for(int i=0;i<3;i++){float gy=500+i*155;if(Math.abs(ny-gy)<22||((y-gy)*(ny-gy)<0)){if(Math.abs(nx-gaps[i])>55||!open(i)){moving=false;bumps++;message="Porte fermée. Attends la prochaine ouverture.";return;}}}x=nx;y=ny;for(int i=0;i<3;i++){float gx=i%2==0?590:125,gy=560+i*140;if(!gems[i]&&Math.hypot(x-gx,y-gy)<30){gems[i]=true;score+=30;message="Détour réussi : +30.";}}if(y<399&&Math.abs(x-360)<65){score+=Math.max(20,100-bumps*5);round++;if(round==3){won=over=true;}else{bumps=0;course();}}}
}
